apply_patch() { python3 - "$1" <<'"'PY'
import sys
patch_path = sys.argv[1]
lines = open(patch_path).read().splitlines()
assert lines[0] == '*** Begin Patch'
for line in lines[1:]:
    if line.startswith('*** Add File: '):
        path = line[len('*** Add File: '):]
        assert not __import__('os').path.exists(path)
        current, mode = [], 'add'
    elif line.startswith('*** Update File: '):
        path = line[len('*** Update File: '):]
        original = open(path).read().splitlines()
        current = []
        mode = 'update'
    elif line.startswith('@@'):
        # This patch only uses whole-file replacement for updates.
        if mode == 'update':
            current = original
    elif line.startswith('-') and mode == 'update':
        if current and current[-1] == line[1:]:
            current.pop()
    elif line.startswith('+'):
        current.append(line[1:])
    elif line == '*** End Patch':
        open(path, 'w').write('\\n'.join(current) + '\\n')
    elif line.startswith('***'):
        raise AssertionError(line)
    else:
        if mode == 'add':
            current.append(line[1:] if line.startswith(' ') else line)
        else:
            raise AssertionError(line)
PY
}
